using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.IO;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace ClearDisk {
 internal sealed class SoftwareInventoryForm:Form {
  readonly SafetyPolicy policy;readonly Button scan=new Button(),cancel=new Button(),open=new Button();readonly TextBox search=new TextBox();readonly Label status=new Label();readonly DataGridView grid=new DataGridView();readonly ListBox warnings=new ListBox();readonly System.Windows.Forms.Timer pulse=new System.Windows.Forms.Timer();readonly object gate=new object();
  SoftwareInventoryReport report;List<SoftwareUsage> visible=new List<SoftwareUsage>();ScanProgress latest;CancellationTokenSource cancellation;bool busy,closing;
  internal SoftwareInventoryForm(SafetyPolicy safety){
   policy=safety;Text="软件占用查询";Font=new Font("Microsoft YaHei UI",9);Size=new Size(1250,800);MinimumSize=new Size(1050,650);StartPosition=FormStartPosition.CenterParent;
   var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(18),ColumnCount=1,RowCount=5};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,55));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,45));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,40));Controls.Add(layout);
   layout.Controls.Add(new Label{Dock=DockStyle.Fill,Text="读取安装软件登记并只读计量其C盘安装目录。登记估算和实测占用分列，父子目录可能重叠。\r\n不修改安装文件、注册表或软件；未登记路径、其他盘和无权限数据保留为未知。",TextAlign=ContentAlignment.MiddleLeft},0,0);
   var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};scan.Text="开始查询";cancel.Text="取消";open.Text="打开安装目录";foreach(var button in new[]{scan,cancel,open}){button.Size=new Size(130,32);actions.Controls.Add(button);}cancel.Enabled=false;open.Enabled=false;search.Width=320;search.Margin=new Padding(12,6,0,0);search.AccessibleName="筛选软件名称、发布者或安装路径";actions.Controls.Add(search);layout.Controls.Add(actions,0,1);
   grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.AllowUserToDeleteRows=false;grid.RowHeadersVisible=false;grid.VirtualMode=true;grid.MultiSelect=false;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.BackgroundColor=Color.White;
   string[] names={"软件名称","版本","发布者","C盘目录逻辑大小","登记估算","安装日期","计量状态","安装目录"};int[] widths={210,110,150,140,110,100,310,440};for(int i=0;i<names.Length;i++)grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText=names[i],Width=widths[i]});
   grid.CellValueNeeded+=delegate(object sender,DataGridViewCellValueEventArgs e){if(e.RowIndex<0||e.RowIndex>=visible.Count)return;var item=visible[e.RowIndex];switch(e.ColumnIndex){case 0:e.Value=item.Installation.Name;break;case 1:e.Value=item.Installation.Version;break;case 2:e.Value=item.Installation.Publisher;break;case 3:e.Value=item.Measured?(item.Incomplete?"至少 ":"")+Display.Size(item.LogicalBytes):"未知 / 未计量";break;case 4:e.Value=item.Installation.EstimatedBytes.HasValue?Display.Size(item.Installation.EstimatedBytes.Value):"未登记";break;case 5:e.Value=item.Installation.InstallDate;break;case 6:e.Value=item.Status;break;case 7:e.Value=item.Root??item.Installation.InstallLocation;break;}};
   grid.SelectionChanged+=delegate{UpdateOpen();};layout.Controls.Add(grid,0,2);warnings.Dock=DockStyle.Fill;warnings.HorizontalScrollbar=true;layout.Controls.Add(warnings,0,3);status.Dock=DockStyle.Fill;status.Text="尚未查询";status.TextAlign=ContentAlignment.MiddleLeft;layout.Controls.Add(status,0,4);
   scan.Click+=async delegate{await Query();};cancel.Click+=delegate{if(cancellation!=null)cancellation.Cancel();};search.TextChanged+=delegate{Filter();};open.Click+=delegate{if(grid.CurrentCell==null||grid.CurrentCell.RowIndex>=visible.Count)return;string path=visible[grid.CurrentCell.RowIndex].Root;if(String.IsNullOrEmpty(path))return;try{using(var pins=new NativeFiles.ParentLocks(Path.Combine(path,".inspect"))){Process.Start(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"explorer.exe"),"\""+path+"\"");}}catch(Exception e){MessageBox.Show(this,"目录无法打开："+e.Message,Text);}};
   pulse.Interval=180;pulse.Tick+=delegate{ScanProgress p;lock(gate){p=latest;latest=null;}if(p!=null)status.Text="已计量 "+p.Files.ToString("N0")+" 个独立文件 · "+Display.Size(p.Bytes)+" · "+p.Message;};FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy){closing=true;e.Cancel=true;cancellation.Cancel();}};FormClosed+=delegate{pulse.Dispose();};
  }
  void Filter(){string text=search.Text.Trim();visible=report==null?new List<SoftwareUsage>():report.Items.Where(i=>text.Length==0||((i.Installation.Name??"")+" "+(i.Installation.Publisher??"")+" "+(i.Installation.InstallLocation??"")).IndexOf(text,StringComparison.OrdinalIgnoreCase)>=0).OrderByDescending(i=>i.Measured?i.LogicalBytes:i.Installation.EstimatedBytes??-1).ToList();grid.RowCount=visible.Count;grid.Invalidate();UpdateOpen();}
  void UpdateOpen(){open.Enabled=!busy&&grid.CurrentCell!=null&&grid.CurrentCell.RowIndex<visible.Count&&!String.IsNullOrEmpty(visible[grid.CurrentCell.RowIndex].Root);}
  internal void LoadReport(SoftwareInventoryReport value){report=value;Filter();warnings.Items.Clear();foreach(string warning in report.Warnings)warnings.Items.Add(warning);status.Text=(report.Cancelled?"已取消":report.Incomplete?"查询已结束（存在未知 / 未检查项）":"查询完成")+" · "+report.Items.Count+" 项登记 · C盘已计量并去重 "+Display.Size(report.UniqueLogicalBytes)+" · "+report.UniqueFiles.ToString("N0")+" 个文件";}
  async Task Query(){if(busy)return;busy=true;scan.Enabled=false;cancel.Enabled=true;open.Enabled=false;search.Enabled=false;cancellation=new CancellationTokenSource();pulse.Start();try{var result=await Task.Run(()=>new SoftwareInventoryScanner(policy).ScanInstalled(cancellation.Token,p=>{lock(gate)latest=p;}));pulse.Stop();lock(gate)latest=null;LoadReport(result);}catch(Exception e){status.Text="软件占用查询未完成："+e.Message;}finally{pulse.Stop();lock(gate)latest=null;cancellation.Dispose();cancellation=null;busy=false;scan.Enabled=true;cancel.Enabled=false;search.Enabled=true;UpdateOpen();if(closing)Close();}}
 }
}
